body.value:
(* Linear scaling of the 4-20mA raw signal to engineering units. *)
PV := Raw_Signal * Scaling_Slope + Scaling_Offset;
(* Wire-break style fault: a healthy 4-20mA loop never drops below ~2mA. *)
General_Fault := Alarm_Enable AND (Raw_Signal < 2.0);
High_Alarm := Alarm_Enable AND (PV > PV_High);
Low_Alarm := Alarm_Enable AND (PV < PV_Low);

Bool_Out := Bool_In;
Alarm_Active := (Alarm_OnTrue AND Bool_In) OR (Alarm_OnFalse AND NOT Bool_In);
IF Reset_Latch THEN
    Latched_Status := FALSE;
ELSIF Latch_Enable AND Alarm_Active THEN
    Latched_Status := TRUE;
END_IF;

(* Pass-through of the field contact (debounce not modeled). *)
DI_Out := DI_Raw;
Fault_State := FALSE;

ActiveIsA := NOT AlternateEnable;
IF Enable AND StartRequest AND NOT Inhibit THEN
    CmdPumpA := ActiveIsA AND NOT PumpA_Fault;
    CmdPumpB := (NOT ActiveIsA OR PumpA_Fault) AND NOT PumpB_Fault;
ELSE
    CmdPumpA := FALSE;
    CmdPumpB := FALSE;
END_IF;
IF ForcePumpA THEN
    CmdPumpA := Enable AND NOT Inhibit;
    CmdPumpB := FALSE;
END_IF;
IF ForcePumpB THEN
    CmdPumpA := FALSE;
    CmdPumpB := Enable AND NOT Inhibit;
END_IF;
SwitchedDueToDuty := DutyElapsed;
SwitchedDueToFailure := PumpA_Fault OR PumpB_Fault;
Alarm_FailedStart_A := PumpA_Fault;
Alarm_FailedStart_B := PumpB_Fault;
Alarm_NoAvailablePump := PumpA_Fault AND PumpB_Fault;

IF Inhibit OR Stop_Cmd THEN
    Motor_Start_Out := FALSE;
ELSIF Start_Cmd THEN
    Motor_Start_Out := TRUE;
END_IF;
FB_Running := Motor_Start_Out;
FB_HighSpeed := Motor_Start_Out AND Speed_High_Cmd;
FB_LowSpeed := Motor_Start_Out AND Speed_Low_Cmd AND NOT Speed_High_Cmd;
FB_Trip := FALSE;
Alarm_Speed_Error := Speed_High_Cmd AND Speed_Low_Cmd;

IF Inhibit OR Stop_Cmd THEN
    Motor_Start_Out := FALSE;
ELSIF Start_Cmd THEN
    Motor_Start_Out := TRUE;
END_IF;
FB_Running := Motor_Start_Out;
FB_Trip := FALSE;
Alarm_Start_Fail := FALSE;
Alarm_Stop_Fail := FALSE;

IF Inhibit OR Stop_Cmd THEN
    FB_Running := FALSE;
ELSIF Start_Cmd THEN
    FB_Running := TRUE;
END_IF;
IF FB_Running THEN
    Speed_Out := Speed_SP;
ELSE
    Speed_Out := 0.0;
END_IF;
FB_Ready := NOT Inhibit;
FB_Fault := FALSE;
FB_ActualSpeed := Speed_Out;
Alarm_Speed_Deviation := FALSE;
Alarm_Comm_Fail := FALSE;

PV_High_Alarm := PV > PV_High;
PV_Low_Alarm := PV < PV_Low;
Deviation_Alarm := ABS(SP - PV) > Deviation_Limit;
(* Bounded proportional control law (single-block, stateless). *)
IF Inhibit THEN
    XOUT := MV_MIN;
ELSIF AUTO THEN
    XOUT := LIMIT(MV_MIN, X0 + KP * (SP - PV), MV_MAX);
ELSE
    XOUT := X0;
END_IF;

IF PrimaryPV > 0.0 THEN
    ActiveRatio := SecondaryPV / PrimaryPV;
ELSE
    ActiveRatio := 0.0;
END_IF;
RatioErr := ActiveRatio - RatioSP;
IF Inhibit THEN
    SlaveSP := MV_MIN;
ELSIF Auto THEN
    SlaveSP := LIMIT(MV_MIN, PrimaryPV * RatioSP + Bias, MV_MAX);
ELSE
    SlaveSP := ManOut;
END_IF;

IF IN <= Split_Point THEN
    OUT1 := Output1_End;
    OUT2 := Output2_Start;
ELSE
    OUT1 := Output1_Start;
    OUT2 := Output2_End;
END_IF;

IF Inhibit THEN
    Valve_Position := Close_Limit;
ELSIF Manual_Mode THEN
    Valve_Position := LIMIT(Close_Limit, Manual_Position, Open_Limit);
ELSE
    Valve_Position := LIMIT(Close_Limit, Control_Signal, Open_Limit);
END_IF;
Feedback_Pos := Valve_Position;
Valve_Moving := FALSE;
Position_Error := FALSE;
Alarm := Inhibit;

IF Inhibit THEN
    Valve_Open_Out := FALSE;
    Valve_Close_Out := TRUE;
ELSE
    Valve_Open_Out := Open_Cmd AND NOT Close_Cmd;
    Valve_Close_Out := Close_Cmd OR NOT Open_Cmd;
END_IF;
FB_Opened := Valve_Open_Out;
FB_Closed := NOT Valve_Open_Out;
Alarm_Position_Error := FALSE;
Alarm_General := Inhibit;

Voted_Output := (Input1 + Input2 + Input3) / 3.0;
Sensor1_Fault := FALSE;
Sensor2_Fault := FALSE;
Sensor3_Fault := FALSE;
Alarm_Voting_Error := FALSE;
Healthy_Sensors_Count := 3;

FT_404(
    PV_Low := 50.0);
FT_406(
    PV_Low := 20.0);
PT_403();
PT_408();
RatioInhibit_OR := PT_403.High_Alarm OR PT_403.Low_Alarm OR FT_404.Low_Alarm OR FT_404.General_Fault OR FT_406.General_Fault OR PT_408.Low_Alarm;
FFIC_402(
    Auto := TRUE,
    PrimaryPV := FT_404.PV,
    SecondaryPV := FT_406.PV,
    RatioSP := 2.5,
    MV_MIN := 0.0,
    MV_MAX := 500.0,
    Inhibit := RatioInhibit_OR);
FIC_406(
    AUTO := TRUE,
    PV := FT_406.PV,
    SP := FFIC_402.SlaveSP);
PIC_401(
    AUTO := TRUE,
    PV := PT_403.PV,
    SP := 5.0,
    PV_High := 6.0,
    PV_Low := 4.0);
ValveInhibit_OR := PT_403.High_Alarm OR PT_403.Low_Alarm OR FT_404.Low_Alarm OR FT_406.Low_Alarm;
CV_406(
    Control_Signal := FIC_406.XOUT,
    Inhibit := ValveInhibit_OR);
CV_401(
    Control_Signal := PIC_401.XOUT);

(* Outputs published to other sections / HMI. *)
FT404_GasFlow_PV := FT_404.PV;
FT406_LiqFlow_PV := FT_406.PV;
PT403_SepPressure_PV := PT_403.PV;
PT408_AuxPressure_PV := PT_408.PV;
FIC406_LiqFlow_SP_From_FFIC402 := FFIC_402.SlaveSP;

LI_201(
    Raw_Signal := LI201_Raw_mA,
    PV_High := 80.0,
    PV_Low := 20.0,
    Scaling_Slope := 6.25,
    Scaling_Offset := -25.0);
XV_010_OPEN_FB(
    DI_Raw := XV010_OpenSw_Raw);
XV_011_OPEN_FB(
    DI_Raw := XV011_OpenSw_Raw);
FlowPathOpen_AND := XV_010_OPEN_FB.DI_Out AND XV_011_OPEN_FB.DI_Out;
LIFaultInvert_NOT := NOT LI_201.General_Fault;
LoopAutoPermissive_AND := LIFaultInvert_NOT AND FlowPathOpen_AND;
FIC_302(
    AUTO := LoopAutoPermissive_AND,
    PV := LI_201.PV,
    SP := 70.0,
    MV_MIN := 0.0,
    MV_MAX := 100.0,
    X0 := 25.0,
    KP := 1.8,
    TR := 2.0,
    TD := 0.3);
NotFlowPathOpen_NOT := NOT FlowPathOpen_AND;
FV101ManualMode_OR := NotFlowPathOpen_NOT OR FIC_302.PV_High_Alarm;
FV_101(
    Control_Signal := FIC_302.XOUT,
    Manual_Mode := FV101ManualMode_OR,
    Manual_Position := 0.0,
    Open_Limit := 100.0,
    Close_Limit := 0.0);

(* Outputs published to other sections / HMI. *)
LI201_Level_PV_Pct := LI_201.PV;
FIC302_MV_To_FV101_Pct := FIC_302.XOUT;
FV101_Feedback_Position_Pct := FV_101.Feedback_Pos;

(* Constant configuration values. *)
FT102_FlowOK_Thresh := 10.0;
ValveOpenFB_Threshold := 90.0;
LevelOK_Threshold := 25.0;

FT_102(
    Scaling_Slope := 6.25,
    Scaling_Offset := -25.0);
FT_104(
    Scaling_Slope := 6.25,
    Scaling_Offset := -25.0);
LI_101(
    PV_High := 90.0,
    PV_Low := 20.0,
    Scaling_Slope := 6.25,
    Scaling_Offset := -25.0);
FIC101_ForceManual_OR := LI_101.Low_Alarm OR LI_101.High_Alarm OR FT_102.General_Fault;
FIC101_AutoEnable_NOT := NOT FIC101_ForceManual_OR;
FIC_101(
    AUTO := FIC101_AutoEnable_NOT,
    PV := FT_102.PV,
    SP := 50.0,
    MV_MIN := 0.0,
    MV_MAX := 100.0,
    X0 := 0.0,
    KP := 2.0,
    TR := 1.0,
    TD := 0.1,
    Deviation_Limit := 10.0);
FIC102_ForceManual_OR := LI_101.Low_Alarm OR LI_101.High_Alarm OR FT_104.General_Fault;
FIC102_AutoEnable_NOT := NOT FIC102_ForceManual_OR;
FIC_102(
    AUTO := FIC102_AutoEnable_NOT,
    PV := FT_104.PV,
    SP := 45.0,
    MV_MIN := 0.0,
    MV_MAX := 100.0,
    X0 := 0.0,
    KP := 2.0,
    TR := 1.0,
    TD := 0.1,
    Deviation_Limit := 8.0);
FT102_GT_10GPM := (FT_102.PV > FT102_FlowOK_Thresh);
FlowOK_TON(
    IN := FT102_GT_10GPM,
    PT := T#8s);
LevelOK_GT25 := (LI_101.PV > LevelOK_Threshold);
ValveFB_GT_90PCT := (FV_103.Feedback_Pos > ValveOpenFB_Threshold);
P001_StartPermissive_AND := P001_Start_Cmd AND LevelOK_GT25 AND ValveFB_GT_90PCT;
P001_Stop_OR := P001_Stop_Cmd OR LI_101.General_Fault;
P_001(
    Start_Cmd := P001_StartPermissive_AND,
    Stop_Cmd := P001_Stop_OR,
    Speed_SP := FIC_102.XOUT,
    Inhibit := LI_101.General_Fault);
ValveOpenPermissive_AND := P_001.FB_Running AND FlowOK_TON.Q;
ValveOpenInhibit_NOT := NOT ValveOpenPermissive_AND;
ValveInhibit_OR := ValveOpenInhibit_NOT OR LI_101.General_Fault;
FV_103(
    Control_Signal := FIC_101.XOUT,
    Manual_Mode := FALSE,
    Manual_Position := 0.0,
    Open_Limit := 25.0,
    Close_Limit := 0.0,
    Inhibit := ValveInhibit_OR);
FIC101_Dev_TON(
    IN := FIC_101.Deviation_Alarm,
    PT := T#15s);
FIC102_Dev_TON(
    IN := FIC_102.Deviation_Alarm,
    PT := T#15s);

(* Outputs published to other sections / HMI. *)
FIC101_Deviation_Alarm_15s := FIC101_Dev_TON.Q;
FIC102_Deviation_Alarm_15s := FIC102_Dev_TON.Q;
FIC101_MV_PCT := FIC_101.XOUT;
FIC102_MV_PCT := FIC_102.XOUT;
P001_Speed_AO_PCT := P_001.Speed_Out;

PIT_106(
    Raw_Signal := PIT106_Raw_mA,
    PV_High := 9.5,
    PV_Low := 0.5,
    Scaling_Slope := 0.625,
    Scaling_Offset := -2.5);
COMP_RUN_PERM(
    Bool_In := CompressorRunPermissive);
CompNotRunning := NOT COMP_RUN_PERM.Bool_Out;
CompStartupDelay(
    IN := COMP_RUN_PERM.Bool_Out,
    PT := T#7s);
StartupNotElapsed := NOT CompStartupDelay.Q;
AirCompInhibit := CompNotRunning OR PIT_106.High_Alarm OR PIT_106.Low_Alarm OR PIT_106.General_Fault OR StartupNotElapsed;
PIC_105(
    AUTO := TRUE,
    PV := PIT_106.PV,
    SP := 8.5,
    MV_MIN := 0.0,
    MV_MAX := 100.0,
    KP := 3.0,
    TR := 1.2,
    TD := 0.3,
    Inhibit := AirCompInhibit);
V_010(
    Control_Signal := PIC_105.XOUT,
    Manual_Mode := FALSE,
    Open_Limit := 100.0,
    Close_Limit := 0.0,
    Inhibit := AirCompInhibit);

(* Outputs published to other sections / HMI. *)
PIT106_PressureBar := PIT_106.PV;
PIC105_MV_Percent := PIC_105.XOUT;
